            if r == h - 1: edges.add("bottom")
            if c == 0: edges.add("left")
            if c == w - 1: edges.add("right")
        adjacent_edges = (
            ("top" in edges and "left" in edges) or
            ("top" in edges and "right" in edges) or
            ("bottom" in edges and "left" in edges) or
            ("bottom" in edges and "right" in edges)
        )
        if adjacent_edges:
            box_area = (r1-r0+1) * (c1-c0+1)
            thinness = len(cells) / box_area
            markers.append((thinness, -len(cells), color))

    if markers:
        _, _, key_color = max(markers)
    else:
        # Otherwise use a singleton-colored clue.
        singles = [(color, cells) for color, cells in comps
                   if color != bg and len(cells) == 1]
        if not singles:
            return [row[:] for row in grid]
        key_color = singles[0][0]

    targets = [(len(cells), cells) for color, cells in comps
               if color != bg and color != key_color]
    if not targets:
        return [row[:] for row in grid]
    _, target = max(targets, key=lambda item: item[0])

    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out
